INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('en-simple-present','en','simple-present','一般现在时','Simple Present',1,'把情况作为习惯或事实陈述。','描述日常或事实','subject + base verb / -s','用于习惯和稳定事实。','第三人称单数通常加 -s。','不自动表示此刻正在发生。','published',0);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-en-simple-present','en-simple-present','en','I eat at home.','我在家吃饭。','不自动表示此刻正在发生。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('en-simple-past','en','simple-past','一般过去时','Simple Past',2,'把事件放在已结束的过去。','讲述过去经历','subject + past form','时间范围已结束时。','go 的过去式是 went。','与现在完成时的视角不同。','published',1);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-en-simple-past','en-simple-past','en','I went home.','我回家了。','与现在完成时的视角不同。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('en-present-perfect','en','present-perfect','现在完成时：到现在为止','Present Perfect',4,'从现在看之前是否发生。','谈到现在为止的完成状态','have / has + past participle','与现在有关的经历或尚未完成的事。','不能把 eaten 换成 ate。','yet 否定句表示到现在还没有；不规定日语必须用对应时态。','published',2);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-en-present-perfect','en-present-perfect','en','I haven''t eaten yet.','我还没吃饭。','yet 否定句表示到现在还没有；不规定日语必须用对应时态。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('en-plan-to','en','plan-to','计划做某事','plan + to-infinitive',2,'说明准备采取的行动。','表达计划','plan to + base verb','主体已有行动意向时。','不用 plan to leaving。','有意向不保证实行。','published',3);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-en-plan-to','en-plan-to','en','I plan to leave tomorrow.','我打算明天离开。','有意向不保证实行。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('en-was-going-to','en','was-going-to','过去的打算','was / were going to',4,'回看过去的意图。','解释原先计划','was / were going to + base verb','讲原先打算及后续变化。','going to 后用动词原形。','单独使用不必然意味着取消；but 提供变化。','published',4);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-en-was-going-to','en-was-going-to','en','I was going to go.','我本来打算去。','单独使用不必然意味着取消；but 提供变化。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('en-be-adjective','en','be-adjective','用形容词描述状态','be + adjective',1,'用形容词说明主语状态。','描述状态','subject + be + adjective','表达感受或性质。','英语通常不能省略 be。','形容词强度不同不改变基本句法。','published',5);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-en-be-adjective','en-be-adjective','en','I am exhausted.','我累坏了。','形容词强度不同不改变基本句法。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('en-may','en','may','可能性：may','may + verb',3,'提出可能发生的情况。','表达不确定性','may + base verb','信息不完全时。','may 后不加 to。','可能性不能机械换算成百分比。','published',6);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-en-may','en-may','en','It may rain.','可能会下雨。','可能性不能机械换算成百分比。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('en-might','en','might','可能性：might','might + verb',3,'以试探的语气谈可能性。','表达不确定性','might + base verb','语气较保留时。','might 后用原形。','与 may 有重叠，不总是较低概率。','published',7);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-en-might','en-might','en','It might rain.','也许会下雨。','与 may 有重叠，不总是较低概率。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('en-can-request','en','can-request','用 can 请求帮助','Can you …?',2,'询问对方能否帮忙。','提出请求','Can you + base verb?','日常请求。','问句不加 do。','礼貌程度依语调和关系而变。','published',8);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-en-can-request','en-can-request','en','Can you help me?','你能帮我吗？','礼貌程度依语调和关系而变。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('ja-te-form','ja','te-form','动词て形','て形',2,'把动词变为连接形式。','连接动作或接续补助形式','食べる→食べて；行く→行って','后接いる等结构时。','行く的て形是行って。','て形本身不是时态。','published',0);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-ja-te-form','ja-te-form','ja','食べてから行きます。','吃完再去。','て形本身不是时态。','[{"text":"食べ","reading":"たべ"},{"text":"てから"},{"text":"行き","reading":"いき"},{"text":"ます。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('ja-te-iru','ja','te-iru','ている：状态与进行','〜ている',3,'表示进行或持续状态；是否完成由语境和谓词决定。','描述进行、结果状态或到目前的完成状况','verb て形 + いる','本例与まだ及否定搭配，表示到现在尚未发生进食。','不能把所有ている都解释为正在。','まだ食べていない常相当于还没吃；不表示吃饭动作正在持续。','published',1);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-ja-te-iru','ja-te-iru','ja','まだ食べていません。','我还没吃饭。','まだ食べていない常相当于还没吃；不表示吃饭动作正在持续。','[{"text":"まだ"},{"text":"食べ","reading":"たべ"},{"text":"ていません。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('ja-polite-negative','ja','polite-negative','礼貌否定','〜ません',2,'礼貌地否定非过去形式。','在礼貌语体中否定','ます干 + ません','与不太熟悉的人交流。','いる→いません，不是いるません。','例中いません否定补助动词いる；与て形组合。','published',2);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-ja-polite-negative','ja-polite-negative','ja','まだ食べていません。','我还没吃饭。','例中いません否定补助动词いる；与て形组合。','[{"text":"まだ"},{"text":"食べ","reading":"たべ"},{"text":"ていません。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('ja-tsumori','ja','tsumori','打算与过去意图','〜つもり（だった）',3,'把行动作为自己的意图。','表达打算','dictionary form + つもりだ / つもりだった','说现在或过去的打算。','否定形式的范围会影响含义。','つもりだった并非英语结构的语法等价物。','published',3);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-ja-tsumori','ja-tsumori','ja','行くつもりだった。','我本来打算去。','つもりだった并非英语结构的语法等价物。','[{"text":"行く","reading":"いく"},{"text":"つもりだった。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('ja-n-desu-ga','ja','n-desu-ga','说明背景并转折','〜んですが',4,'把情况作为背景提出，再接转折或铺垫。','柔和地说明缘由','plain form + んですが','说明计划变化或提出话题。','名词及な形容词接なんですが。','が可以留下未说完的余地；此例后接实际转折。','published',4);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-ja-n-desu-ga','ja-n-desu-ga','ja','行くつもりだったんですが、急に用事ができました。','我本来打算去，但是临时有事。','が可以留下未说完的余地；此例后接实际转折。','[{"text":"行く","reading":"いく"},{"text":"つもりだったんですが、"},{"text":"急","reading":"きゅう"},{"text":"に"},{"text":"用事","reading":"ようじ"},{"text":"ができました。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('ja-polite-past','ja','polite-past','礼貌过去式','〜ました',2,'以礼貌语体报告已发生的事。','讲述过去事件','ます干 + ました','报告事情的发生。','できる→できました。','不与所有英语过去时用法一一对应。','published',5);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-ja-polite-past','ja-polite-past','ja','用事ができました。','有事要办了。','不与所有英语过去时用法一一对应。','[{"text":"用事","reading":"ようじ"},{"text":"ができました。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('ja-copula','ja','copula','名词与な形容词的礼貌陈述','〜です',1,'礼貌地判断或说明状态。','描述状态','noun / な-adjective stem + です','中性礼貌对话。','不要把です机械接在动词原形后。','くたくたです表达很累的状态。','published',6);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-ja-copula','ja-copula','ja','大丈夫です。','没关系。','くたくたです表达很累的状态。','[{"text":"大丈夫","reading":"だいじょうぶ"},{"text":"です。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('ja-kamoshirenai','ja','kamoshirenai','不确定的可能性','〜かもしれない',3,'保留判断，承认某种可能。','表达推测','plain form + かもしれない','没有充分把握时。','名词后不用だ再接かもしれない。','与そうだ的证据来源和接续不同。','published',7);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-ja-kamoshirenai','ja-kamoshirenai','ja','雨かもしれません。','可能会下雨。','与そうだ的证据来源和接续不同。','[{"text":"雨","reading":"あめ"},{"text":"かもしれません。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('ja-sou','ja','sou','看起来要发生','〜そうだ（样态）',3,'根据眼前迹象判断。','表达外观上的推测','verb ます干 + そうだ','从可观察迹象推测。','不要与普通形+そうだ的传闻用法混淆。','样态并不是所有可能性的通用形式。','published',8);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-ja-sou','ja-sou','ja','雨が降りそうです。','看起来要下雨。','样态并不是所有可能性的通用形式。','[{"text":"雨","reading":"あめ"},{"text":"が"},{"text":"降り","reading":"ふり"},{"text":"そうです。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,publication_state,sort_order) VALUES ('ja-te-kudasai','ja','te-kudasai','请对方做某事','〜てください',2,'直接而礼貌地请求行动。','请求帮助','verb て形 + ください','需要明确请求时。','手伝う→手伝って。','对上级使用时可能过于直接。','published',9);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('ge-ja-te-kudasai','ja-te-kudasai','ja','手伝ってください。','请帮忙。','对上级使用时可能过于直接。','[{"text":"手伝って","reading":"てつだって"},{"text":"ください。"}]');
